<?php require_once "../config/database.php";require_once "../config/auth.php";require_role('admin');if(isset($_GET['toggle'])){$id=(int)$_GET['toggle'];$conn->query("UPDATE restaurants SET status=IF(status='open','closed','open') WHERE id=$id");header("Location:restaurants.php");exit;}$rows=$conn->query("SELECT r.*,u.name merchant_name FROM restaurants r LEFT JOIN users u ON u.id=r.merchant_id ORDER BY r.id DESC");?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Nhà hàng</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Quản lý nhà hàng</h1><table class="table"><tr><th>Tên</th><th>Địa chỉ</th><th>Merchant</th><th>Trạng thái</th><th></th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['address'])?></td><td><?=htmlspecialchars($r['merchant_name']??'')?></td><td><?=$r['status']?></td><td><a class="btn secondary" href="?toggle=<?=$r['id']?>">Đổi trạng thái</a></td></tr><?php endwhile;?></table><p><a class="btn secondary" href="index.php">← Admin</a></p></main></body></html>